<script module lang="ts">
/**
 * MultiSelect.Chip: one chosen value, with its remove button, playing its exit when it is removed.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/multi-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot, watchEffect } from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/multi-select.module.css'

export interface MultiSelectChipProps {
  label: string
  /**
   * False once the value is removed, while the chip plays its exit.
   */
  open: boolean
  /**
   * The chip joined after the list’s first render, so it plays its enter.
   */
  appear: boolean
  disabled: boolean
  /**
   * The remove button’s accessible name.
   */
  removeLabel: string
  onRemove?: () => void
  onKeyDown?: (event: KeyboardEvent) => void
  /**
   * The exit has played, and the member can drop the chip.
   */
  onDone?: () => void
}
</script>

<script lang="ts">
let {
  label: labelOwn,
  open,
  appear,
  disabled,
  removeLabel,
  onRemove,
  onKeyDown,
  onDone,
}: MultiSelectChipProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, disabled: disabled }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let chip = $state<HTMLElement | null>(null)
const present = usePresence(
  () => open,
  () => chip,
  'taginput.chip',
  {
    get appear() {
      return appear
    },
    reflow: 'taginput.reflow',
  },
)
const effect1 = () => {
  present.current || onDone?.()
}
watchEffect(effect1, { watch: () => present.current, mount: false })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li bind:this={chip} class={styles.chip} data-removing={(!open) ? '' : undefined}
    ><span class={styles.label}>{label}</span
    >{#if !disabled
      }<button
        class={styles.remove}
        type="button"
        aria-label={removeLabel}
        onclick={() => { onRemove?.() }}
        onkeydown={(event) => { onKeyDown?.(event) }}
        ><Icon name="close" size="sm"
      /></button
    >{/if
  }</li
>{/if
}{@render joined.end?.()}
